{"bytes": 10546379, "encoding": "PACKLINES1", "lines": [{"text": "#!/bin/bash\n"}, {"text": "set -euo pipefail\n"}, {"text": "umask 077\n"}, {"text": "export PATH=/usr/local/bin:/usr/bin:/bin HOME=/tmp USER=jjyeung CUDA_VISIBLE_DEVICES=\n"}, {"text": "trap 'rc=$?; if [ \"$rc\" != 0 ]; then printf \"phase exit %s line %s\\n\" \"$rc\" \"$LINENO\" >&2; fi' EXIT\n"}, {"text": "/usr/bin/python3 -I -s -B - <<'PYCODE'\n"}, {"text": "import hashlib,io,os,tarfile\n"}, {"text": "from pathlib import Path\n"}, {"text": "os.umask(0o077)\n"}, {"block": "085622f6d66db23db31572ea8751af1aba7788a452cd0c5bf21c43a4af533847"}, {"text": "assert hashlib.sha256(raw).hexdigest()=='2b076fd20aaf43987b191bd10f6cb1ed1cf8e167be20c4f57c92037a1bd2a457'\n"}, {"text": "if p.exists():\n"}, {"text": "    assert not p.is_symlink() and p.stat().st_uid==os.getuid() and not p.stat().st_mode & 0o077\n"}, {"text": "    assert {x.name for x in p.iterdir()}=={'v'} and (p/'v').is_dir() and not (p/'v').is_symlink(), 'Not a verify-only root'\n"}, {"text": "else:p.mkdir(mode=0o700)\n"}, {"text": "(p/'a').mkdir(mode=0o700)\n"}, {"text": "with tarfile.open(fileobj=io.BytesIO(raw)) as t:\n"}, {"text": "    seen=set()\n"}, {"text": "    for m in t:\n"}, {"text": "        q=Path(m.name)\n"}, {"text": "        assert m.isfile() and not q.is_absolute() and '..' not in q.parts and m.name not in seen\n"}, {"text": "        seen.add(m.name);f=p/q;f.parent.mkdir(parents=True,exist_ok=True,mode=0o700)\n"}, {"text": "        with f.open('xb') as out:out.write(t.extractfile(m).read())\n"}, {"text": "        f.chmod(0o600)\n"}, {"text": "(p/'a').chmod(0o700)\n"}, {"text": "print('placed')\n"}, {"text": "\n"}, {"text": "PYCODE\n"}], "path": "work/r3/native/pack_build/commands/place.sh", "sha256": "5a8a88e9d16c4d49b3f2d615fb1e408ca99cc0fb26a77305e262c51d83bbf14f"}
